import sys
import os
import csv
import json

def parse_date(val):
    val = val.strip()
    if not val:
        return None
    # Input format: MM/DD/YYYY
    parts = val.split('/')
    if len(parts) == 3:
        return f"{parts[2].zfill(4)}-{parts[0].zfill(2)}-{parts[1].zfill(2)}"
    return val

def load_file(dir_path, filename):
    filepath = os.path.join(dir_path, filename)
    if not os.path.exists(filepath):
        return []
    rows = []
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter='|')
        header = None
        for row in reader:
            if not row:
                continue
            first_cell = row[0].strip()
            if first_cell.startswith('#'):
                continue
            if header is None:
                header = [c.strip() for c in row]
            else:
                row_dict = {header[i]: row[i].strip() if i < len(row) else '' for i in range(len(header))}
                rows.append(row_dict)
    return rows

def get_entity_values(rows, entity_id, col_name, is_date=False):
    vals = set()
    for r in rows:
        if r.get('WORKER_FILE_NUMBER') == entity_id:
            raw = r.get(col_name, '').strip()
            if raw:
                v = parse_date(raw) if is_date else raw
                if v:
                    vals.add(v)
    return vals

def resolve_fact(entity_id, doc_specs):
    # doc_specs is a list of (doc_name, rows, col_name, is_date)
    for doc_name, rows, col_name, is_date in doc_specs:
        vals = get_entity_values(rows, entity_id, col_name, is_date)
        if len(vals) > 1:
            return "CONFLICT"
        elif len(vals) == 1:
            return [list(vals)[0], doc_name]
    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    dol_receipts = load_file(dir_path, 'dol_receipts.txt')
    ead_cards = load_file(dir_path, 'ead_cards.txt')
    hr_roster = load_file(dir_path, 'hr_roster.txt')
    lca_filings = load_file(dir_path, 'lca_filings.txt')
    lca_notices = load_file(dir_path, 'lca_notices.txt')
    reverifications = load_file(dir_path, 'reverifications.txt')
    work_authorizations = load_file(dir_path, 'work_authorizations.txt')

    entities = [f"E-401{i:02d}" for i in range(1, 17)]

    output = {}

    for eid in entities:
        pair_id = f"wf.reverify_window::{eid}"
        auth_exp = resolve_fact(eid, [
            ('work_authorizations', work_authorizations, 'EMPLOYABILITY_EVIDENCE_LAPSE', True),
            ('ead_cards', ead_cards, 'I766_VALID_TO', True)
        ])
        reverif = resolve_fact(eid, [
            ('reverifications', reverifications, 'SUPPLEMENT_B_EXECUTED', True)
        ])
        output[pair_id] = {
            "authorization expiry": auth_exp,
            "reverification date": reverif
        }

    for eid in entities:
        pair_id = f"wf.notice_posting::{eid}"
        n_posted = resolve_fact(eid, [
            ('lca_notices', lca_notices, 'NOTICE_DISPLAY_BEGIN', True)
        ])
        n_removed = resolve_fact(eid, [
            ('lca_notices', lca_notices, 'NOTICE_DISPLAY_END', True)
        ])
        lca_filed = resolve_fact(eid, [
            ('lca_filings', lca_filings, 'ETA9035_SUBMISSION_DAY', True),
            ('dol_receipts', dol_receipts, 'OFLC_INTAKE_DAY', True)
        ])
        output[pair_id] = {
            "notice posted": n_posted,
            "notice removed": n_removed,
            "LCA filed": lca_filed
        }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
