```python
import sys
import os
import re
import json

MONTHS = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'sept': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12,
}

def parse_date(text):
    m = re.search(r'\b([A-Za-z]+)\.?\s+(\d{1,2}),\s+(\d{4})\b', text)
    if not m:
        return None
    month_name, day, year = m.groups()
    month_key = month_name.lower().rstrip('.')
    if month_key not in MONTHS:
        return None
    month = MONTHS[month_key]
    return f"{int(year):04d}-{month:02d}-{int(day):02d}"

def clean_html(text):
    text = re.sub(r'<[^>]+>', ' ', text)
    text = text.replace('&nbsp;', ' ').replace('&mdash;', '—').replace('&middot;', '·')
    return ' '.join(text.split())

def parse_html_file(file_path):
    if not os.path.exists(file_path):
        return {}
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    articles = re.findall(r'<article\b[^>]*>(.*?)</article>', content, re.DOTALL | re.IGNORECASE)
    records = []

    for art in articles:
        rows = re.findall(r'<tr\b[^>]*>(.*?)</tr>', art, re.DOTALL | re.IGNORECASE)
        sheet_data = {}
        for row in rows:
            th_m = re.search(r'<th\b[^>]*>(.*?)</th>', row, re.DOTALL | re.IGNORECASE)
            td_m = re.search(r'<td\b([^>]*)>(.*?)</td>', row, re.DOTALL | re.IGNORECASE)
            if th_m and td_m:
                header = clean_html(th_m.group(1)).strip()
                attrs = td_m.group(1)
                raw_td = td_m.group(2)
                if 'void' in attrs.lower() or 'left blank' in raw_td.lower():
                    continue
                val = clean_html(raw_td).strip()
                if val:
                    sheet_data[header] = val
        if 'Staff badge' in sheet_data:
            badge = sheet_data['Staff badge']
            records.append((badge, sheet_data))

    return records

def extract_values(records, field_name, is_date=True):
    badge_map = {}
    for badge, sheet_data in records:
        if badge not in badge_map:
            badge_map[badge] = []
        if field_name in sheet_data:
            val = sheet_data[field_name]
            if is_date:
                d = parse_date(val)
                if d:
                    badge_map[badge].append(d)
            else:
                badge_map[badge].append(val)
    return badge_map

def resolve_fact(badge, primary_doc_name, primary_data, fallback_doc_name=None, fallback_data=None):
    primary_vals = primary_data.get(badge, [])
    if primary_vals:
        unique = list(dict.fromkeys(primary_vals))
        if len(unique) == 1:
            return [unique[0], primary_doc_name]
        else:
            return "CONFLICT"

    if fallback_doc_name and fallback_data is not None:
        fb_vals = fallback_data.get(badge, [])
        if fb_vals:
            unique = list(dict.fromkeys(fb_vals))
            if len(unique) == 1:
                return [unique[0], fallback_doc_name]
            else:
                return "CONFLICT"

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    doc_files = {
        'dol_receipts': 'dol_receipts.html',
        'ead_cards': 'ead_cards.html',
        'hr_roster': 'hr_roster.html',
        'lca_filings': 'lca_filings.html',
        'lca_notices': 'lca_notices.html',
        'reverifications': 'reverifications.html',
        'work_authorizations': 'work_authorizations.html',
    }

    parsed_docs = {}
    all_badges = set()
    for doc_name, filename in doc_files.items():
        records = parse_html_file(os.path.join(dir_path, filename))
        parsed_docs[doc_name] = records
        for badge, _ in records:
            all_badges.add(badge)

    badges = sorted(all_badges)

    wa_expiry = extract_values(parsed_docs['work_authorizations'], 'Evidence expires', is_date=True)
    ead_expiry = extract_values(parsed_docs['ead_cards'], 'EAD valid to', is_date=True)
    reverif_date = extract_values(parsed_docs['reverifications'], 'Supplement B signed on', is_date=True)

    notice_posted = extract_values(parsed_docs['lca_notices'], 'Notice first displayed', is_date=True)
    notice_removed = extract_values(parsed_docs['lca_notices'], 'Notice withdrawn from display', is_date=True)
    lca_filed = extract_values(parsed_docs['lca_filings'], 'Submitted through FLAG', is_date=True)
    dol_receipt = extract_values(parsed_docs['dol_receipts'], 'Agency receipt notice dated', is_date=True)

    output = {}

    for badge in badges:
        pair_id = f"wf.reverify_window::{badge}"
        output[pair_id] = {
            "authorization expiry": resolve_fact(badge, 'work_authorizations', wa_expiry, 'ead_cards', ead_expiry),
            "reverification date": resolve_fact(badge, 'reverifications', reverif_date)
        }

    for badge in badges:
        pair_id = f"wf.notice_posting::{badge}"
        output[pair_id] = {
            "notice posted": resolve_fact(badge, 'lca_notices', notice_posted),
            "notice removed": resolve_fact(badge, 'lca_notices', notice_removed),
            "LCA filed": resolve_fact(badge, 'lca_filings', lca_filed, 'dol_receipts', dol_receipt)
        }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
