```python
import sys
import os
import json
import re
import datetime

MONTHS = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12
}

def parse_date(s):
    if not s:
        return None
    m1 = re.search(r'\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\s+(\d{4})\b', s)
    if m1:
        day = int(m1.group(1))
        mon_str = m1.group(2).lower()
        year = int(m1.group(3))
        if mon_str in MONTHS:
            try:
                return datetime.date(year, MONTHS[mon_str], day)
            except ValueError:
                pass
    m2 = re.search(r'\b([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b', s)
    if m2:
        mon_str = m2.group(1).lower()
        day = int(m2.group(2))
        year = int(m2.group(3))
        if mon_str in MONTHS:
            try:
                return datetime.date(year, MONTHS[mon_str], day)
            except ValueError:
                pass
    return None

def find_dates(text):
    dates = []
    p1 = re.compile(r'\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\s+(\d{4})\b')
    for m in p1.finditer(text):
        day = int(m.group(1))
        mon_str = m.group(2).lower()
        year = int(m.group(3))
        if mon_str in MONTHS:
            try:
                d = datetime.date(year, MONTHS[mon_str], day)
                dates.append((m.start(), d))
            except ValueError:
                pass
    p2 = re.compile(r'\b([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b')
    for m in p2.finditer(text):
        mon_str = m.group(1).lower()
        day = int(m.group(2))
        year = int(m.group(3))
        if mon_str in MONTHS:
            try:
                d = datetime.date(year, MONTHS[mon_str], day)
                dates.append((m.start(), d))
            except ValueError:
                pass
    dates.sort(key=lambda x: x[0])
    unique_dates = []
    seen_pos = set()
    for pos, d in dates:
        if pos not in seen_pos:
            seen_pos.add(pos)
            unique_dates.append(d)
    return unique_dates

def read_file(dir_path, base_name):
    for name in [f"{base_name}.txt", base_name]:
        p = os.path.join(dir_path, name)
        if os.path.exists(p):
            with open(p, 'r', encoding='utf-8', errors='replace') as f:
                return f.read().replace('\r\n', '\n')
    return ""

def split_messages(file_content):
    raw_msgs = re.split(r'=+\n', file_content)
    messages = []
    for raw in raw_msgs:
        raw = raw.strip()
        if not raw or 'From:' not in raw:
            continue
        parts = raw.split('\n\n', 1)
        headers = parts[0]
        body = parts[1] if len(parts) > 1 else ''
        m = re.search(r'\b(E-\d+)\b', headers)
        if not m:
            m = re.search(r'\b(E-\d+)\b', body)
        ent = m.group(1) if m else None
        messages.append((ent, headers, body))
    return messages

def parse_work_authorizations(dir_path):
    content = read_file(dir_path, 'work_authorizations')
    msgs = split_messages(content)
    res = {}
    for ent, headers, body in msgs:
        if not ent:
            continue
        if re.search(r'\b(?:no|not)\b.*?\b(?:end-of-validity|expiry|validity)\b', body, re.I):
            continue
        dates = find_dates(body)
        if dates:
            d_str = dates[0].strftime('%Y-%m-%d')
            res.setdefault(ent, set()).add(d_str)
    return res

def parse_ead_cards(dir_path):
    content = read_file(dir_path, 'ead_cards')
    msgs = split_messages(content)
    res = {}
    for ent, headers, body in msgs:
        if not ent:
            continue
        if re.search(r'\bno\b.*?\b(?:end\s+date|expiry|card)\b', body, re.I):
            continue
        dates = find_dates(body)
        if dates:
            d_str = dates[0].strftime('%Y-%m-%d')
            res.setdefault(ent, set()).add(d_str)
    return res

def parse_reverifications(dir_path):
    content = read_file(dir_path, 'reverifications')
    msgs = split_messages(content)
    res = {}
    for ent, headers, body in msgs:
        if not ent:
            continue
        if re.search(r'\bno\b.*?\b(?:sign-off\s+day|sign-off|re-verification)\b', body, re.I):
            continue
        dates = find_dates(body)
        if dates:
            d_str = dates[0].strftime('%Y-%m-%d')
            res.setdefault(ent, set()).add(d_str)
    return res

def parse_lca_filings(dir_path):
    content = read_file(dir_path, 'lca_filings')
    msgs = split_messages(content)
    res = {}
    for ent, headers, body in msgs:
        if not ent:
            continue
        if re.search(r"(?:don't have|no)\b.*?\bFLAG\b", body, re.I):
            continue
        dates = find_dates(body)
        if dates:
            d_str = dates[0].strftime('%Y-%m-%d')
            res.setdefault(ent, set()).add(d_str)
    return res

def parse_dol_receipts(dir_path):
    content = read_file(dir_path, 'dol_receipts')
    msgs = split_messages(content)
    res = {}
    for ent, headers, body in msgs:
        if not ent:
            continue
        if re.search(r'\bno\b.*?\b(?:acknowledgment\s+date|acknowledgment)\b', body, re.I):
            continue
        dates = find_dates(body)
        if dates:
            d_str = dates[0].strftime('%Y-%m-%d')
            res.setdefault(ent, set()).add(d_str)
    return res

def parse_lca_notices(dir_path):
    content = read_file(dir_path, 'lca_notices')
    msgs = split_messages(content)
    posted_res = {}
    removed_res = {}
    for ent, headers, body in msgs:
        if not ent:
            continue
        # Posted date
        posted_d = None
        if not re.search(r"\b(?:can't tell|no)\b.*?\b(?:went up|pinned up|posted)\b", body, re.I):
            m_post = re.search(r'(?:went up(?: on the board)? on|pinned(?: the notice)? up on|posted(?: on)?)\s+([A-Za-z0-9, ]+?)(?:\.|\band came down|\n|$)', body, re.I)
            if m_post:
                posted_d = parse_date(m_post.group(1))
            else:
                dates = find_dates(body)
                if dates:
                    posted_d = dates[0]
            if posted_d:
                posted_res.setdefault(ent, set()).add(posted_d.strftime('%Y-%m-%d'))

        # Removed date
        m_rel = re.search(r'came down\s+(\d+)\s+days later', body, re.I)
        if m_rel and posted_d:
            removed_d = posted_d + datetime.timedelta(days=int(m_rel.group(1)))
            removed_res.setdefault(ent, set()).add(removed_d.strftime('%Y-%m-%d'))
        else:
            if not re.search(r"\b(?:can't tell|no)\b.*?\b(?:pulled down|taken off|came down)\b", body, re.I):
                m_rem = re.search(r'(?:pulled(?: the notice)? down on|taken off(?: the board)? on|came down on|removed(?: on)?)\s+([A-Za-z0-9, ]+?)(?:\.|\n|$)', body, re.I)
                if m_rem:
                    removed_d = parse_date(m_rem.group(1))
                    if removed_d:
                        removed_res.setdefault(ent, set()).add(removed_d.strftime('%Y-%m-%d'))

    return posted_res, removed_res

def resolve_fact(primary_dict, primary_doc, fallback_dict=None, fallback_doc=None, entity=None):
    prim_vals = primary_dict.get(entity, set())
    if len(prim_vals) > 1:
        return "CONFLICT"
    elif len(prim_vals) == 1:
        return [list(prim_vals)[0], primary_doc]

    if fallback_dict is not None:
        fb_vals = fallback_dict.get(entity, set())
        if len(fb_vals) > 1:
            return "CONFLICT"
        elif len(fb_vals) == 1:
            return [list(fb_vals)[0], fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    # Collect entities
    all_entities = set()
    for fname in os.listdir(dir_path):
        p = os.path.join(dir_path, fname)
        if os.path.isfile(p):
            with open(p, 'r', encoding='utf-8', errors='replace') as f:
                matches = re.findall(r'\b(E-\d+)\b', f.read())
                all_entities.update(matches)

    def sort_key(e):
        m = re.search(r'\d+', e)
        return int(m.group(0)) if m else 0

    sorted_entities = sorted(all_entities, key=sort_key)

    work_auth = parse_work_authorizations(dir_path)
    ead_cards = parse_ead_cards(dir_path)
    reverif = parse_reverifications(dir_path)
    lca_filings = parse_lca_filings(dir_path)
    dol_receipts = parse_dol_receipts(dir_path)
    lca_posted, lca_removed = parse_lca_notices(dir_path)

    result = {}

    # wf.reverify_window
    for ent in sorted_entities:
        pair_id = f"wf.reverify_window::{ent}"
        pair_obj = {}
        pair_obj["authorization expiry"] = resolve_fact(work_auth, "work_authorizations", ead_cards, "ead_cards", ent)
        pair_obj["reverification date"] = resolve_fact(reverif, "reverifications", entity=ent)
        result[pair_id] = pair_obj

    # wf.notice_posting
    for ent in sorted_entities:
        pair_id = f"wf.notice_posting::{ent}"
        pair_obj = {}
        pair_obj["notice posted"] = resolve_fact(lca_posted, "lca_notices", entity=ent)
        pair_obj["notice removed"] = resolve_fact(lca_removed, "lca_notices", entity=ent)
        pair_obj["LCA filed"] = resolve_fact(lca_filings, "lca_filings", dol_receipts, "dol_receipts", ent)
        result[pair_id] = pair_obj

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
