```python
import sys
import os
import re
import json
import datetime

MONTH_NAMES = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'sept': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12
}

def parse_date_str(text):
    if not text:
        return None
    # Match ISO format
    m = re.search(r'\b(\d{4})-(\d{2})-(\d{2})\b', text)
    if m:
        return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"

    m_name = r'(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)'

    # Month Day, Year
    m1 = re.search(rf'\b({m_name})\s+(\d{{1,2}})(?:st|nd|rd|th)?,?\s+(\d{{4}})\b', text, re.IGNORECASE)
    if m1:
        mon = MONTH_NAMES[m1.group(1).lower()]
        day = int(m1.group(2))
        yr = int(m1.group(3))
        return f"{yr:04d}-{mon:02d}-{day:02d}"

    # Day Month Year
    m2 = re.search(rf'\b(\d{{1,2}})(?:st|nd|rd|th)?\s+({m_name})\s+(\d{{4}})\b', text, re.IGNORECASE)
    if m2:
        day = int(m2.group(1))
        mon = MONTH_NAMES[m2.group(2).lower()]
        yr = int(m2.group(3))
        return f"{yr:04d}-{mon:02d}-{day:02d}"

    return None

def split_mailbox_messages(content):
    raw_msgs = content.split('========================================================================')
    messages = []
    for raw in raw_msgs:
        raw = raw.strip()
        if not raw:
            continue
        if re.search(r'^(?:From|Subject|Date|To):', raw, re.MULTILINE):
            parts = re.split(r'\r?\n\r?\n', raw, maxsplit=1)
            header = parts[0]
            body = parts[1] if len(parts) > 1 else ""
        else:
            header = ""
            body = raw

        sub_m = re.search(r'Subject:.*?\b(E-\d+)\b', header)
        if sub_m:
            entity = sub_m.group(1)
        else:
            ent_m = re.search(r'\b(E-\d+)\b', raw)
            entity = ent_m.group(1) if ent_m else None

        if entity:
            messages.append((entity, header, body))
    return messages

def read_file(dir_path, filename):
    path = os.path.join(dir_path, filename)
    if os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            return f.read()
    return ""

def parse_work_authorizations(content):
    data = {}
    for entity, header, body in split_mailbox_messages(content):
        if re.search(r'\bno\s+end-of-validity\b|\bno\s+validity\b|\bno\s+record\b|\bno\s+date\b', body, re.IGNORECASE):
            continue
        dt = parse_date_str(body)
        if dt:
            data.setdefault(entity, set()).add(dt)
    return data

def parse_ead_cards(content):
    data = {}
    for entity, header, body in split_mailbox_messages(content):
        if re.search(r'\bno\s+end\s+date\b|\bno\s+card\b|\bno\s+record\b|\bno\s+date\b', body, re.IGNORECASE):
            continue
        dt = parse_date_str(body)
        if dt:
            data.setdefault(entity, set()).add(dt)
    return data

def parse_reverifications(content):
    data = {}
    for entity, header, body in split_mailbox_messages(content):
        if re.search(r'\bno\s+sign-off\b|\bno\s+re-verification\b|\bno\s+record\b|\bno\s+date\b', body, re.IGNORECASE):
            continue
        dt = parse_date_str(body)
