def parse_lca_filings(content):
    data = {}
    for entity, header, body in split_mailbox_messages(content):
        if re.search(r'\bdon\'t have a FLAG submission\b|\bno\s+FLAG\b|\bno\s+submission\b|\bno\s+record\b|\bno\s+date\b', body, re.IGNORECASE):
            continue
