        if re.search(r'\bno\s+acknowledgment\b|\bno\s+receipt\b|\bno\s+record\b|\bno\s+date\b', body, re.IGNORECASE):
            continue
        dt = parse_date_str(body)
        if dt:
            data.setdefault(entity, set()).add(dt)
    return data

def parse_lca_notices(content):
    posted_data = {}
    removed_data = {}
    for entity, header, body in split_mailbox_messages(content):
        # Notice posted
        p_date = None
        if not re.search(r'\bno\s+posting\b|\bno\s+record\s+of\s+when\s+it\s+went\s+up\b', body, re.IGNORECASE):
            m_post = re.search(r'(?:went up on the board on|pinned the notice up on|posted on)\s+([^.\n]+)', body, re.IGNORECASE)
            if m_post:
                p_date = parse_date_str(m_post.group(1))
            else:
                p_date = parse_date_str(body)
            if p_date:
                posted_data.setdefault(entity, set()).add(p_date)

        # Notice removed
        r_date = None
        if re.search(r'\bno\s+record\s+of\s+when\s+it\s+was\s+pulled\s+down\b|\bno\s+removal\b', body, re.IGNORECASE):
            r_date = None
        else:
            m_days = re.search(r'came down\s+(\d+)\s+days later', body, re.IGNORECASE)
            if m_days and p_date:
                days = int(m_days.group(1))
                p_dt = datetime.date.fromisoformat(p_date)
                r_date = (p_dt + datetime.timedelta(days=days)).isoformat()
            else:
                m_rem = re.search(r'(?:pulled the notice down on|taken off the board on|came down on|removed on)\s+([^.\n]+)', body, re.IGNORECASE)
                if m_rem:
                    r_date = parse_date_str(m_rem.group(1))
        if r_date:
            removed_data.setdefault(entity, set()).add(r_date)

    return posted_data, removed_data

def resolve_fact(entity, primary_doc_name, primary_data, fallback_doc_name=None, fallback_data=None):
    primary_vals = primary_data.get(entity, set())
    if len(primary_vals) > 1:
        return "CONFLICT"
    elif len(primary_vals) == 1:
        return [next(iter(primary_vals)), primary_doc_name]
    else:
        if fallback_doc_name and fallback_data is not None:
            fallback_vals = fallback_data.get(entity, set())
            if len(fallback_vals) > 1:
                return "CONFLICT"
            elif len(fallback_vals) == 1:
                return [next(iter(fallback_vals)), fallback_doc_name]
            else:
                return "ABSENT"
        else:
            return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    # Read files
    work_auth_content = read_file(dir_path, "work_authorizations.txt")
    ead_cards_content = read_file(dir_path, "ead_cards.txt")
    reverif_content = read_file(dir_path, "reverifications.txt")
    lca_filings_content = read_file(dir_path, "lca_filings.txt")
    dol_receipts_content = read_file(dir_path, "dol_receipts.txt")
    lca_notices_content = read_file(dir_path, "lca_notices.txt")

    # Parse facts from documents
    work_auth_data = parse_work_authorizations(work_auth_content)
    ead_cards_data = parse_ead_cards(ead_cards_content)
    reverif_data = parse_reverifications(reverif_content)
    lca_filings_data = parse_lca_filings(lca_filings_content)
    dol_receipts_data = parse_dol_receipts(dol_receipts_content)
    notice_posted_data, notice_removed_data = parse_lca_notices(lca_notices_content)

    # Find all entities across all files
    entities = set()
    for root, _, files in os.walk(dir_path):
        for f in files:
            if f.endswith('.txt'):
                text = read_file(root, f)
                found = re.findall(r'\bE-\d+\b', text)
                entities.update(found)

    def sort_key(e):
        m = re.search(r'\d+', e)
        return int(m.group(0)) if m else e

    sorted_entities = sorted(entities, key=sort_key)

    rules = ["wf.reverify_window", "wf.notice_posting"]
    output = {}

    for rule in rules:
        for entity in sorted_entities:
            pair_id = f"{rule}::{entity}"
            if rule == "wf.reverify_window":
                auth_exp = resolve_fact(entity, "work_authorizations", work_auth_data, "ead_cards", ead_cards_data)
                rev_date = resolve_fact(entity, "reverifications", reverif_data)
                output[pair_id] = {
                    "authorization expiry": auth_exp,
                    "reverification date": rev_date
                }
            elif rule == "wf.notice_posting":
                posted = resolve_fact(entity, "lca_notices", notice_posted_data)
                removed = resolve_fact(entity, "lca_notices", notice_removed_data)
                lca_filed = resolve_fact(entity, "lca_filings", lca_filings_data, "dol_receipts", dol_receipts_data)
                output[pair_id] = {
                    "notice posted": posted,
                    "notice removed": removed,
                    "LCA filed": lca_filed
                }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
