import re
import datetime

def parse_week_date(val):
    val = val.strip()
    if not val or val == '~':
        return None
    m = re.match(r'^(\d{4})-W(\d{2})-(\d)$', val)
    if m:
        year, week, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
        return datetime.date.fromisocalendar(year, week, day).isoformat()
    return val

def load_tsv(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = [line.strip('\r\n') for line in f if line.strip() and not line.startswith('#')]
    if not lines:
        return []
    rows = [line.split('\t') for line in lines]
    num_cols = len(rows[0])
    records = []
    for c in range(1, num_cols):
        rec = {}
        for r in rows:
            attr = r[0].strip()
            val = r[c].strip() if c < len(r) else ''
            rec[attr] = val
        records.append(rec)
    return records

def get_distinct_values(docs, doc_name, worker, attr_name):
    recs = docs.get(doc_name, [])
    raw_vals = [r.get(attr_name) for r in recs if r.get('worker.key') == worker]
    parsed_vals = []
    for v in raw_vals:
        if v is not None:
            formatted = parse_week_date(v)
            if formatted is not None:
                parsed_vals.append(formatted)
    return list(dict.fromkeys(parsed_vals))

def resolve_fact(docs, worker, primary_doc, primary_attr, fallback_doc=None, fallback_attr=None):
    vals_prim = get_distinct_values(docs, primary_doc, worker, primary_attr)
    if len(vals_prim) > 1:
        return "CONFLICT"
    elif len(vals_prim) == 1:
        return [vals_prim[0], primary_doc]

    if fallback_doc and fallback_attr:
        vals_fb = get_distinct_values(docs, fallback_doc, worker, fallback_attr)
        if len(vals_fb) > 1:
            return "CONFLICT"
        elif len(vals_fb) == 1:
            return [vals_fb[0], fallback_doc]

    return "ABSENT"

def main():
