        'reverifications': 'reverifications.tsv',
        'work_authorizations': 'work_authorizations.tsv',
    }

    docs = {}
    for doc_name, filename in doc_files.items():
        filepath = os.path.join(dir_path, filename)
        docs[doc_name] = load_tsv(filepath)

    workers = set()
    for recs in docs.values():
        for r in recs:
            k = r.get('worker.key')
            if k and k != '~':
                workers.add(k.strip())
    sorted_workers = sorted(workers)

    rules = [
        (
            'wf.reverify_window',
            [
                ('authorization expiry', 'work_authorizations', 'eligibility.doc.lapse.wk', 'ead_cards', 'ead.lapse.wk'),
                ('reverification date', 'reverifications', 'i9.redo.done.wk', None, None),
            ]
        ),
