            [
                ('notice posted', 'lca_notices', 'board.pinned.wk', None, None),
                ('notice removed', 'lca_notices', 'board.unpinned.wk', None, None),
                ('LCA filed', 'lca_filings', 'lca.lodge.wk', 'dol_receipts', 'agency.stamp.wk'),
            ]
        )
    ]

    output = {}
    for rule_name, fact_defs in rules:
        for worker in sorted_workers:
            pair_id = f"{rule_name}::{worker}"
            pair_result = {}
            for fact_name, prim_doc, prim_attr, fb_doc, fb_attr in fact_defs:
                pair_result[fact_name] = resolve_fact(docs, worker, prim_doc, prim_attr, fb_doc, fb_attr)
            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
