MONTHS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4,
    'may': 5, 'jun': 6, 'jul': 7, 'aug': 8,
    'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
}

def parse_date(text):
    m = re.search(r'([A-Za-z]+)\.?\s+(\d{1,2}),\s+(\d{4})', text)
    if not m:
        return None
    month_str = m.group(1)[:3].lower()
    month = MONTHS.get(month_str)
    if not month:
        return None
    day = int(m.group(2))
    year = int(m.group(3))
    return f"{year:04d}-{month:02d}-{day:02d}"

def clean_html(text):
    return re.sub(r'<[^>]+>', '', text).strip()

def parse_file(file_path):
    if not os.path.isfile(file_path):
        return []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    sheets = re.findall(r'<article\b[^>]*>(.*?)</article>', content, re.DOTALL)
    records = []
    for sheet in sheets:
        rows = re.findall(r'<tr\b[^>]*>\s*<th\b[^>]*>(.*?)</th>\s*<td\b([^>]*)>(.*?)</td>\s*</tr>', sheet, re.DOTALL)
        sheet_data = {}
        for th, td_attrs, td in rows:
            th_clean = clean_html(th)
            if 'void' in td_attrs or 'left blank' in td.lower():
                continue
            val_clean = clean_html(td)
            if val_clean and val_clean != '—':
                sheet_data[th_clean] = val_clean
        if 'Staff badge' in sheet_data:
            records.append(sheet_data)
    return records

def collect_records(records, badge_key='Staff badge'):
    by_badge = {}
    for r in records:
        badge = r.get(badge_key)
        if badge:
            by_badge.setdefault(badge, []).append(r)
    return by_badge

def resolve_fact(badge, primary_doc, primary_records, primary_field, fallback_doc=None, fallback_records=None, fallback_field=None):
    primary_sheets = primary_records.get(badge, [])
    primary_vals = []
    for s in primary_sheets:
        if primary_field in s:
            d = parse_date(s[primary_field])
            if d:
                primary_vals.append(d)

    if primary_vals:
        unique_vals = set(primary_vals)
        if len(unique_vals) > 1:
            return "CONFLICT"
        return [primary_vals[0], primary_doc]

    if fallback_doc and fallback_records is not None:
        fallback_sheets = fallback_records.get(badge, [])
        fallback_vals = []
        for s in fallback_sheets:
            if fallback_field in s:
                d = parse_date(s[fallback_field])
                if d:
                    fallback_vals.append(d)
        if fallback_vals:
            unique_vals = set(fallback_vals)
            if len(unique_vals) > 1:
                return "CONFLICT"
            return [fallback_vals[0], fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    work_authorizations = collect_records(parse_file(os.path.join(dir_path, "work_authorizations.html")))
    ead_cards = collect_records(parse_file(os.path.join(dir_path, "ead_cards.html")))
    reverifications = collect_records(parse_file(os.path.join(dir_path, "reverifications.html")))
    lca_notices = collect_records(parse_file(os.path.join(dir_path, "lca_notices.html")))
    lca_filings = collect_records(parse_file(os.path.join(dir_path, "lca_filings.html")))
    dol_receipts = collect_records(parse_file(os.path.join(dir_path, "dol_receipts.html")))

    badges = [f"E-407{i:02d}" for i in range(1, 17)]

    out = {}

    for b in badges:
        pair_id = f"wf.reverify_window::{b}"
        auth_exp = resolve_fact(b, "work_authorizations", work_authorizations, "Evidence expires",
                                fallback_doc="ead_cards", fallback_records=ead_cards, fallback_field="EAD valid to")
        rev_date = resolve_fact(b, "reverifications", reverifications, "Supplement B signed on")
        out[pair_id] = {
            "authorization expiry": auth_exp,
            "reverification date": rev_date
        }

    for b in badges:
        pair_id = f"wf.notice_posting::{b}"
        n_posted = resolve_fact(b, "lca_notices", lca_notices, "Notice first displayed")
        n_removed = resolve_fact(b, "lca_notices", lca_notices, "Notice withdrawn from display")
        lca_filed = resolve_fact(b, "lca_filings", lca_filings, "Submitted through FLAG",
                                 fallback_doc="dol_receipts", fallback_records=dol_receipts, fallback_field="Agency receipt notice dated")
        out[pair_id] = {
            "notice posted": n_posted,
            "notice removed": n_removed,
            "LCA filed": lca_filed
        }

    print(json.dumps(out, indent=2))

if __name__ == '__main__':
    main()
