    'sep': 9, 'sept': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12
}

def parse_date(text):
    if not text:
        return None
    text = html.unescape(text)
    if 'left blank' in text.lower():
        return None
    m = re.search(r'([A-Za-z]+)\.?\s+(\d{1,2}),?\s+(\d{4})', text)
    if not m:
        return None
    month_str, day_str, year_str = m.groups()
    month_key = month_str.lower().rstrip('.')
    if month_key not in MONTHS:
        return None
    month = MONTHS[month_key]
    day = int(day_str)
    year = int(year_str)
    return f"{year:04d}-{month:02d}-{day:02d}"

def clean_text(text):
    text = re.sub(r'<[^>]+>', '', text)
    return html.unescape(text).strip()

def parse_sheets(file_path):
    if not os.path.exists(file_path):
        return []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    articles = re.findall(r'<article\s+class="sheet"[^>]*>(.*?)</article>', content, re.DOTALL | re.IGNORECASE)
    sheets_data = []
    for art in articles:
        sheet = {}
        rows = re.findall(r'<tr>(.*?)</tr>', art, re.DOTALL | re.IGNORECASE)
        for row in rows:
            th_m = re.search(r'<th[^>]*>(.*?)</th>', row, re.DOTALL | re.IGNORECASE)
            td_m = re.search(r'<td[^>]*>(.*?)</td>', row, re.DOTALL | re.IGNORECASE)
            if th_m and td_m:
                label = clean_text(th_m.group(1))
                val_raw = td_m.group(1)
                if 'void' in td_m.group(0):
                    val = None
                else:
                    val = clean_text(val_raw)
                sheet[label] = val
        sheets_data.append(sheet)
    return sheets_data

def get_entity_values(sheets, field_label, is_date=True):
    entity_vals = {}
    for sheet in sheets:
        badge = sheet.get("Staff badge")
        if not badge:
            continue
        badge = badge.strip()
        val = sheet.get(field_label)
        if val:
            if is_date:
                parsed = parse_date(val)
                if parsed:
                    entity_vals.setdefault(badge, []).append(parsed)
            else:
                entity_vals.setdefault(badge, []).append(val)
    return entity_vals

def resolve_fact(entity, primary_doc, primary_vals, fallback_doc=None, fallback_vals=None):
    vals = primary_vals.get(entity, [])
    if vals:
        unique_vals = list(set(vals))
        if len(unique_vals) > 1:
            return "CONFLICT"
        return [unique_vals[0], primary_doc]

    if fallback_doc and fallback_vals is not None:
        f_vals = fallback_vals.get(entity, [])
        if f_vals:
            unique_f_vals = list(set(f_vals))
            if len(unique_f_vals) > 1:
                return "CONFLICT"
            return [unique_f_vals[0], fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
