    notices_sheets = parse_sheets(os.path.join(directory, "lca_notices.html"))
    filings_sheets = parse_sheets(os.path.join(directory, "lca_filings.html"))
    receipts_sheets = parse_sheets(os.path.join(directory, "dol_receipts.html"))

    wa_expiries = get_entity_values(wa_sheets, "Evidence expires", is_date=True)
