    rev_dates = get_entity_values(rev_sheets, "Supplement B signed on", is_date=True)

    notices_posted = get_entity_values(notices_sheets, "Notice first displayed", is_date=True)
    notices_removed = get_entity_values(notices_sheets, "Notice withdrawn from display", is_date=True)
    filings_lca = get_entity_values(filings_sheets, "Submitted through FLAG", is_date=True)
    receipts_dol = get_entity_values(receipts_sheets, "Agency receipt notice dated", is_date=True)

    entities = [f"E-408{i:02d}" for i in range(1, 17)]
    result = {}

    for entity in entities:
        pair_id = f"wf.reverify_window::{entity}"
        auth_exp = resolve_fact(entity, "work_authorizations", wa_expiries, "ead_cards", ead_expiries)
        rev_date = resolve_fact(entity, "reverifications", rev_dates)
