import sys
import os
import json
import sqlite3
import datetime

def epd_to_date(epd):
    return (datetime.date(1970, 1, 1) + datetime.timedelta(days=epd)).isoformat()

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    # Map document name to filename, table, worker col, and fact col mappings
    doc_configs = {
        'work_authorizations': {
            'file': 'work_authorizations.sql',
            'table': 'eligibility_doc',
            'cols': {'authorization expiry': 'eligibility_doc_lapse_epd'}
        },
        'ead_cards': {
            'file': 'ead_cards.sql',
            'table': 'ead_card',
            'cols': {'authorization expiry': 'ead_lapse_epd'}
        },
        'reverifications': {
            'file': 'reverifications.sql',
            'table': 'i9_redo',
            'cols': {'reverification date': 'i9_redo_done_epd'}
        },
        'lca_filings': {
            'file': 'lca_filings.sql',
            'table': 'lca_lodgement',
            'cols': {'LCA filed': 'lca_lodge_epd'}
        },
        'dol_receipts': {
            'file': 'dol_receipts.sql',
            'table': 'agency_ack',
            'cols': {'LCA filed': 'agency_stamp_epd'}
        },
        'lca_notices': {
            'file': 'lca_notices.sql',
            'table': 'lca_board_notice',
            'cols': {
                'notice posted': 'board_pinned_epd',
                'notice removed': 'board_unpinned_epd'
            }
        }
    }

    # Load databases
    conns = {}
    for doc_name, cfg in doc_configs.items():
        file_path = os.path.join(dir_path, cfg['file'])
        conn = sqlite3.connect(':memory:')
        if os.path.exists(file_path):
            with open(file_path, 'r', encoding='utf-8') as f:
                conn.executescript(f.read())
        conns[doc_name] = conn

    def get_fact_value(doc_name, fact_name, wkr_code):
        cfg = doc_configs[doc_name]
        col = cfg['cols'][fact_name]
        table = cfg['table']
        conn = conns[doc_name]
        cur = conn.cursor()
        query = f"SELECT DISTINCT {col} FROM {table} WHERE wkr_code = ? AND {col} IS NOT NULL"
        try:
            cur.execute(query, (wkr_code,))
            rows = cur.fetchall()
        except sqlite3.OperationalError:
            rows = []
        return [r[0] for r in rows]

    def resolve_fact(wkr_code, fact_name, primary_doc, fallback_doc=None):
        vals = get_fact_value(primary_doc, fact_name, wkr_code)
        if len(vals) > 1:
            return "CONFLICT"
        elif len(vals) == 1:
            return [epd_to_date(vals[0]), primary_doc]

        # Primary has no value
        if fallback_doc:
            fallback_vals = get_fact_value(fallback_doc, fact_name, wkr_code)
            if len(fallback_vals) > 1:
                return "CONFLICT"
            elif len(fallback_vals) == 1:
                return [epd_to_date(fallback_vals[0]), fallback_doc]

        return "ABSENT"

    worker_ids = [f"E-409{i:02d}" for i in range(1, 17)]
    output = {}

    for wkr in worker_ids:
        pair_id = f"wf.reverify_window::{wkr}"
        output[pair_id] = {
            "authorization expiry": resolve_fact(wkr, "authorization expiry", "work_authorizations", "ead_cards"),
            "reverification date": resolve_fact(wkr, "reverification date", "reverifications")
        }

    for wkr in worker_ids:
        pair_id = f"wf.notice_posting::{wkr}"
        output[pair_id] = {
            "notice posted": resolve_fact(wkr, "notice posted", "lca_notices"),
            "notice removed": resolve_fact(wkr, "notice removed", "lca_notices"),
            "LCA filed": resolve_fact(wkr, "LCA filed", "lca_filings", "dol_receipts")
        }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
