import sys
import os
import json

def parse_edi_loops(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    segments = [s.strip() for s in content.split('~') if s.strip()]
    loops = []
    current_loop = None

    for seg in segments:
        parts = [p.strip() for p in seg.split('*')]
        tag = parts[0]
        if tag == 'LX':
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = []
        elif current_loop is not None:
            if tag in ('CTT', 'SE', 'GE', 'IEA'):
                loops.append(current_loop)
                current_loop = None
            else:
                current_loop.append(parts)
    if current_loop is not None:
        loops.append(current_loop)
    return loops

def format_date(val):
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    return val

def extract_file_data(filepath, target_dtp_qualifier):
    loops = parse_edi_loops(filepath)
    entity_values = {}
    for loop in loops:
        entity_id = None
        vals = []
        for parts in loop:
            if parts[0] == 'REF' and len(parts) > 2 and parts[1] == 'EI':
                entity_id = parts[2]
            elif parts[0] == 'DTP' and len(parts) > 3 and parts[1] == target_dtp_qualifier and parts[2] == 'D8':
                vals.append(format_date(parts[3]))
        if entity_id:
            if entity_id not in entity_values:
                entity_values[entity_id] = []
            entity_values[entity_id].extend(vals)
    return entity_values

def resolve_fact(entity, primary_doc, primary_vals, fallback_doc=None, fallback_vals=None):
    p_list = primary_vals.get(entity, [])
    unique_p = sorted(list(set(p_list)))
    if len(unique_p) > 1:
        return "CONFLICT"
    elif len(unique_p) == 1:
        return [unique_p[0], primary_doc]

    if fallback_doc is not None and fallback_vals is not None:
        f_list = fallback_vals.get(entity, [])
        unique_f = sorted(list(set(f_list)))
        if len(unique_f) > 1:
            return "CONFLICT"
        elif len(unique_f) == 1:
            return [unique_f[0], fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    # Data stores
    # work_authorizations: DTP*036
    wa_vals = extract_file_data(os.path.join(dir_path, 'work_authorizations.edi'), '036')
    # ead_cards: DTP*438
    ead_vals = extract_file_data(os.path.join(dir_path, 'ead_cards.edi'), '438')
    # reverifications: DTP*572
    rev_vals = extract_file_data(os.path.join(dir_path, 'reverifications.edi'), '572')
    # lca_notices: DTP*196 (posted), DTP*197 (removed)
    notice_posted_vals = extract_file_data(os.path.join(dir_path, 'lca_notices.edi'), '196')
    notice_removed_vals = extract_file_data(os.path.join(dir_path, 'lca_notices.edi'), '197')
    # lca_filings: DTP*640
    lca_filed_vals = extract_file_data(os.path.join(dir_path, 'lca_filings.edi'), '640')
    # dol_receipts: DTP*009
    dol_receipts_vals = extract_file_data(os.path.join(dir_path, 'dol_receipts.edi'), '009')

    entities = [f"E-{i}" for i in range(41001, 41017)]
    result = {}

    for eid in entities:
        # wf.reverify_window
        pair_key_rw = f"wf.reverify_window::{eid}"
        auth_exp = resolve_fact(eid, 'work_authorizations', wa_vals, 'ead_cards', ead_vals)
        rev_date = resolve_fact(eid, 'reverifications', rev_vals)
        result[pair_key_rw] = {
            "authorization expiry": auth_exp,
            "reverification date": rev_date
        }

        # wf.notice_posting
        pair_key_np = f"wf.notice_posting::{eid}"
        not_posted = resolve_fact(eid, 'lca_notices', notice_posted_vals)
        not_removed = resolve_fact(eid, 'lca_notices', notice_removed_vals)
        lca_filed = resolve_fact(eid, 'lca_filings', lca_filed_vals, 'dol_receipts', dol_receipts_vals)
        result[pair_key_np] = {
            "notice posted": not_posted,
            "notice removed": not_removed,
            "LCA filed": lca_filed
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
