```python
import sys
import re
import os
import json
from datetime import datetime, timedelta

MONTHS = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12
}

def parse_date_str(s):
    # Pattern 1: DD(st|nd|rd|th)? Month YYYY
    m1 = re.search(r'(\b\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\s+(\d{4})\b', s)
    if m1:
        day = int(m1.group(1))
        mon_str = m1.group(2).lower()
        year = int(m1.group(3))
        if mon_str in MONTHS:
            return datetime(year, MONTHS[mon_str], day).strftime('%Y-%m-%d')

    # Pattern 2: Month DD(st|nd|rd|th)?,? YYYY
    m2 = re.search(r'\b([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b', s)
    if m2:
        mon_str = m2.group(1).lower()
        day = int(m2.group(2))
        year = int(m2.group(3))
        if mon_str in MONTHS:
            return datetime(year, MONTHS[mon_str], day).strftime('%Y-%m-%d')

    return None

def parse_messages(text):
    messages = []
    blocks = re.split(r'={10,}', text)
    for b in blocks:
        b = b.strip()
        if not b or 'From:' not in b:
            continue
        messages.append(b)
    return messages

def get_entity_id(msg):
    m = re.search(r'\b(E-\d{5})\b', msg)
    return m.group(1) if m else None

def parse_work_authorizations(dirpath):
    filepath = os.path.join(dirpath, 'work_authorizations.txt')
    if not os.path.exists(filepath):
        return {}
    with open(filepath, 'r', encoding='utf-8') as f:
        text = f.read()

    data = {}
    for msg in parse_messages(text):
        eid = get_entity_id(msg)
        if not eid:
            continue
        if eid not in data:
            data[eid] = []

        # Check negative statements
        if re.search(r'no end-of-validity', msg, re.I):
            continue

        # Look for validity date
        # "That evidence stops being valid on ..." / "It is good only up to ..."
        m = re.search(r'(?:stops being valid on|good only up to)\s+([^.\n]+)', msg, re.I)
        if m:
            d = parse_date_str(m.group(1))
            if d:
                data[eid].append(d)
    return data

def parse_ead_cards(dirpath):
    filepath = os.path.join(dirpath, 'ead_cards.txt')
    if not os.path.exists(filepath):
        return {}
    with open(filepath, 'r', encoding='utf-8') as f:
        text = f.read()

    data = {}
    for msg in parse_messages(text):
        eid = get_entity_id(msg)
        if not eid:
            continue
        if eid not in data:
            data[eid] = []

        if re.search(r'no\s+.*date', msg, re.I):
            continue

        m = re.search(r'(?:end date of|runs to)\s+([^.\n]+)', msg, re.I)
        if m:
            d = parse_date_str(m.group(1))
            if d:
                data[eid].append(d)
    return data

def parse_reverifications(dirpath):
    filepath = os.path.join(dirpath, 'reverifications.txt')
    if not os.path.exists(filepath):
        return {}
    with open(filepath, 'r', encoding='utf-8') as f:
        text = f.read()

    data = {}
    for msg in parse_messages(text):
        eid = get_entity_id(msg)
        if not eid:
            continue
        if eid not in data:
            data[eid] = []

        if re.search(r'no\s+.*date', msg, re.I):
            continue

        m = re.search(r'(?:signed off on|finished the re-verification on)\s+([^.\n]+)', msg, re.I)
        if m:
            d = parse_date_str(m.group(1))
            if d:
                data[eid].append(d)
    return data

def parse_lca_notices(dirpath):
    filepath = os.path.join(dirpath, 'lca_notices.txt')
    if not os.path.exists(filepath):
        return {}, {}
    with open(filepath, 'r', encoding='utf-8') as f:
        text = f.read()

    posted_data = {}
    removed_data = {}

    for msg in parse_messages(text):
        eid = get_entity_id(msg)
        if not eid:
            continue
        if eid not in posted_data:
            posted_data[eid] = []
        if eid not in removed_data:
            removed_data[eid] = []

        # Posted date
        # "notice went up on the board on March 29th, 2026"
        # "pinned the notice up on February 4th, 2026"
        # Negative: "can't tell you when the notice went up"
        posted_date = None
        if not re.search(r"can't tell you when the notice went up", msg, re.I):
            m_post = re.search(r'(?:went up on the board on|pinned the notice up on)\s+([^.\n]+)', msg, re.I)
            if m_post:
                posted_date = parse_date_str(m_post.group(1))
                if posted_date:
                    posted_data[eid].append(posted_date)

        # Removed date
        # "came down 28 days later"
        # "taken off the board on 18th Apr 2026"
        # "pulled the notice down on May 27th, 2026"
        # Negative: "no record of when it was pulled down"
        if not re.search(r'no record of when it was pulled down', msg, re.I):
            m_rel = re.search(r'came down\s+(\d+)\s+days later', msg, re.I)
            if m_rel and posted_date:
                days = int(m_rel.group(1))
                dt = datetime.strptime(posted_date, '%Y-%m-%d') + timedelta(days=days)
                removed_data[eid].append(dt.strftime('%Y-%m-%d'))
            else:
                m_rem = re.search(r'(?:taken off the board on|pulled the notice down on)\s+([^.\n]+)', msg, re.I)
                if m_rem:
                    d = parse_date_str(m_rem.group(1))
                    if d:
                        removed_data[eid].append(d)

    return posted_data, removed_data

def parse_lca_filings(dirpath):
    filepath = os.path.join(dirpath, 'lca_filings.txt')
    if not os.path.exists(filepath):
        return {}
    with open(filepath, 'r', encoding='utf-8') as f:
        text = f.read()

    data = {}
    for msg in parse_messages(text):
        eid = get_entity_id(msg)
        if not eid:
            continue
        if eid not in data:
            data[eid] = []

        if re.search(r"don't have a FLAG submission day|no\s+.*date", msg, re.I):
            continue

        m = re.search(r'(?:pushed the LCA into FLAG on|submitted through FLAG on)\s+([^.\n]+)', msg, re.I)
        if m:
            d = parse_date_str(m.group(1))
            if d:
                data[eid].append(d)
    return data

def parse_dol_receipts(dirpath):
    filepath = os.path.join(dirpath, 'dol_receipts.txt')
    if not os.path.exists(filepath):
        return {}
    with open(filepath, 'r', encoding='utf-8') as f:
        text = f.read()

    data = {}
    for msg in parse_messages(text):
        eid = get_entity_id(msg)
        if not eid:
            continue
        if eid not in data:
            data[eid] = []

        if re.search(r'no acknowledgment date', msg, re.I):
            continue

        m = re.search(r"(?:agency acknowledged it on|acknowledgment is dated)\s+([^.\n]+)", msg, re.I)
        if m:
            d = parse_date_str(m.group(1))
            if d:
                data[eid].append(d)
    return data

def resolve_fact(primary_doc_name, primary_list, fallback_doc_name=None, fallback_list=None):
    if primary_list:
        distinct = sorted(list(set(primary_list)))
        if len(distinct) == 1:
            return [distinct[0], primary_doc_name]
        else:
            return "CONFLICT"

    if fallback_doc_name and fallback_list:
        distinct = sorted(list(set(fallback_list)))
        if len(distinct) == 1:
            return [distinct[0], fallback_doc_name]
        else:
            return "CONFLICT"

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return
    dirpath = sys.argv[1]

    wa_data = parse_work_authorizations(dirpath)
    ead_data = parse_ead_cards(dirpath)
    rev_data = parse_reverifications(dirpath)
    posted_data, removed_data = parse_lca_notices(dirpath)
    lca_data = parse_lca_filings(dirpath)
    dol_data = parse_dol_receipts(dirpath)

    pairs = [
        ("wf.reverify_window", "E-41001"),
