        ("wf.notice_posting", "E-41015"),
        ("wf.notice_posting", "E-41016")
    ]

    out = {}
    for rule, eid in pairs:
        pair_id = f"{rule}::{eid}"
        if rule == "wf.reverify_window":
            auth_exp = resolve_fact("work_authorizations", wa_data.get(eid, []), "ead_cards", ead_data.get(eid, []))
            rev_date = resolve_fact("reverifications", rev_data.get(eid, []))
            out[pair_id] = {
                "authorization expiry": auth_exp,
