            }
        elif rule == "wf.notice_posting":
            n_posted = resolve_fact("lca_notices", posted_data.get(eid, []))
            n_removed = resolve_fact("lca_notices", removed_data.get(eid, []))
            lca_filed = resolve_fact("lca_filings", lca_data.get(eid, []), "dol_receipts", dol_data.get(eid, []))
            out[pair_id] = {
                "notice posted": n_posted,
                "notice removed": n_removed,
                "LCA filed": lca_filed
            }

    print(json.dumps(out, indent=2))

if __name__ == '__main__':
    main()
